<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Review moderation | LocalPro</title>@vite(['resources/css/app.css','resources/ts/app.ts'])</head><body><header class="topbar"><a class="brand" href="{{ route('admin.dashboard') }}"><span class="brand-mark">✓</span><span>local<span>pro</span><small>ADMIN PORTAL</small></span></a><nav class="main-nav"><a href="{{ route('admin.dashboard') }}">Dashboard</a><a class="active" href="{{ route('admin.reports.index') }}">Reviews</a></nav></header><main class="requests-page"><div class="requests-heading"><div><div class="eyebrow muted">TRUST & SAFETY</div><h1>Review moderation</h1><p>Hide reviews that violate marketplace guidelines. Hidden reviews are excluded from provider ratings.</p></div></div>@if(session('status'))<div class="flash-note">✓ {{ session('status') }}</div>@endif<div class="admin-provider-list">@forelse($reviews as $review)<article class="admin-provider-card"><div class="admin-provider-info"><strong>{{ str_repeat('★',$review->rating) }}{{ str_repeat('☆',5-$review->rating) }} · {{ $review->provider->user->name }}</strong><span>By {{ $review->customer->name }} · {{ $review->created_at->format('M j, Y') }}</span><small>{{ $review->comment ?: 'Rating only' }}</small></div><span class="status-pill {{ $review->status==='published'?'status-approved':'status-rejected' }}">{{ ucfirst($review->status) }}</span><form method="POST" action="{{ route('admin.reviews.toggle',$review) }}">@csrf @method('PATCH')<button class="button button-secondary">{{ $review->status==='published'?'Hide':'Publish' }}</button></form></article>@empty<p class="admin-empty">No reviews have been submitted.</p>@endforelse</div><div class="pagination">{{ $reviews->links() }}</div></main></body></html>
